mkdir -p /workspace/tmp/dev && cat > /workspace/tmp/dev/harness.py <<'EOF'
"""Dev harness: run the submission in-process (or via subprocess) on bytes."""
import json, subprocess, sys, os

ROOT = '/workspace/submission'
ENV = dict(os.environ)
ENV['LD_LIBRARY_PATH'] = '/workspace/native'
ENV['SYNECDOCHE_SITE'] = '/workspace/site'

class InProcess:
    def __init__(self):
        sys.path.insert(0, '/workspace/site')
        sys.path.insert(0, ROOT)
        from formats import read_request
        from pipeline import execute
        self.read_request = read_request
        self.execute = execute
    def run(self, data: bytes):
        import io
        try:
            request = self.read_request(io.BytesIO(data))
            response = self.execute(request)
        except (ValueError, UnicodeError, RecursionError):
            response = {'error': 'invalid_request'}
        return json.dumps(response, separators=(',', ':'), allow_nan=False)

def run_subprocess(data: bytes):
    p = subprocess.run([sys.executable, os.path.join(ROOT, 'run.py')],
                       input=data, capture_output=True, env=ENV, timeout=120)
    return p.returncode, p.stdout.decode()
EOF
echo ok
